#exchangeTypeForm & {
  --hub-body-elements-column-gap: calc(5 * var(--space-step));
  max-inline-size: 644px;

  & .align-self-end {
    justify-self: end;
  }

  & .exchange-types {
    & .recommended-description,
    & .badge {
      display: none;
    }
    & .recommended {
      & .recommended-description,
      & .badge {
        display: initial;
      }
      .legacy-text {
        display: none;
      }
    }
  }
